mod solution;

fn main() {
    let cases = [
    (r#"1->2->4 and 1->3->4"#, r#"1,1,2,3,4,4"#),
    (r#"1->3 and 2->4"#, r#"1,2,3,4"#),
    (r#"
1->3 and 2->4
"#, r#"1,2,3,4"#),
    (r#"  
1->2->4 and 1->3->4
  "#, r#"1,1,2,3,4,4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS merge-two-lists");
}
